  "firstMeeting.fallback": "Так это вы меня разбудили. Рада сотрудничеству.",
  "firstMeeting.rex": "Я — королева битвы.",
  "firstMeeting.torika": "Я встану впереди, капитан!",
  "firstMeeting.spino": "…Где угодно, лишь бы слышать воду.",
  "firstMeeting.luka": "Бег — моё. Сразу после дивана.",
  "firstMeeting.dodo": "Капитан, гляди! Открытие века!",
  "firstMeeting.tia": "Всё, что блестит, — моё!",
  "firstMeeting.stella": "Я уже прочла ветер, сэмпай.",
  "firstMeeting.meron": "А? Тебе… не нравится…?",
  "firstMeeting.pachi": "Эй, посторонись! Расчищаю путь боссу.",
  "firstMeeting.maki": "Постой, я вообще-то врач, знаешь?",
  "firstMeeting.keris": "Смотри только на меня, сэмпай.",
  "firstMeeting.delopi": "Та-дам! Вот ваш ключ, исследователь.",
  "firstMeeting.nodonia": "Скажи, когда будет больно, малыш. Я приму удар за тебя.",
  "firstMeeting.ella": "Я удержу позицию. Тыл за мной.",
  "firstMeeting.mette": "Сцена только для тебя начинается сейчас.",
  "firstMeeting.deina": "Да что ты знаешь об искусстве?",
  "firstMeeting.maddy": "Кондиционер на максимум, пожалуйста.",
  "firstMeeting.terisa": "Если что порвётся… я зашью, малыш.",
  "firstMeeting.parua": "Далеко… так далеко! Мне всё видно.",
  "firstMeeting.shute": "Я же сказала — не то! Следуй моему приказу.",
  "firstMeeting.morphe": "Выпускай всех. Я посмотрю отсюда.",
  "firstMeeting.dian": "Я защищу тебя, капитан! …Ой, Куро! Широ!",
