  "city.doppel-parlor.description": "Гостиная сбоку от Центральной исследовательской лаборатории Доппеля. Гостей усаживают и подают дневники исследований по странице.",
  "city.doppel-lab.description": "Внутренний исследовательский институт в глубине лаборатории Доппеля. Здесь собраны дневники исследователей, когда-то отправленных в Этернал.",
  "city.doppel-lab.displayName": "Доппель · Внутренний исследовательский институт",
  "city.doppel-office.description": "Административный отдел Доппеля, который сводит результаты исследований и сведения о применении реликвий. Согласования проходят много ступеней, поэтому ждать приходится долго.",
  "city.doppel-office.displayName": "Доппель · Административный отдел",
  "city.rust-garage.description": "Ремонтный цех Раста. Заявки на починку сломанного исследовательского оборудования поступают без перерыва.",
  "city.rust-garage.displayName": "Раст · Ремонтный цех",
  "city.rust-lease.description": "Отдел управления арендой Раста, сдающий высокопроизводительное оборудование. Даже одно продление тянет за собой долгие переговоры.",
  "city.rust-lease.displayName": "Раст · Отдел аренды",
  "city.doppel-upper.description": "Верхний этаж лаборатории Доппеля. Здесь сидят те, кто определяет цель исследований.",
  "city.doppel-upper.displayName": "Доппель · Верхнее руководство",
  "city.rust-works.description": "Огромная литейная в самом сердце Раста. Проектирование и ремонт исследовательского оборудования собраны в одном месте.",
  "city.rust-works.displayName": "Раст · Центральная литейная",
  "city.odidi-embassy.description": "Приёмная, где Одиди, город исследователей снов, принимает внешних гостей. Предложения всегда первыми делают они.",
  "city.odidi-embassy.displayName": "Одиди · Дипломатическая приёмная",
  "journal.interaction-doppel-lab-01.title": "Дневник командировки, из которой не вернулись",
  "journal.interaction-doppel-lab-01.body": "Дневник исследователя, отправленного в Этернал. Последняя страница — одна строка: «Смена прибыла», а поле для подписи под ней пусто.",
  "city.department.exchange": "Обменная контора",
  "city.department.council": "Совет",
  "city.doppel-parlor.displayName": "Доппель · Гостиная Центральной лаборатории",
