  "journal.interaction-doppel-01.body": "На первой доске объявлений оранжереи всё ещё просят встречать восстановленных как новых соседей, а не как зрелище.",
  "journal.interaction-doppel-02.title": "Повторяющееся приветствие",
  "bond.torika.0": "Ты кто?",
  "bond.torika.1": "Ты снова здесь.",
  "bond.torika.2": "Можешь побыть рядом.",
  "bond.torika.3": "Что будем делать сегодня?",
  "bond.torika.4": "Я узнаю твои шаги.",
  "bond.torika.5": "Вместе спокойно.",
  "bond.torika.6": "Я прикрою тебе спину.",
  "bond.torika.7": "Я ждала.",
  "bond.torika.8": "С тобой мне спокойно.",
  "bond.torika.9": "Я пойду с тобой до конца.",
  "bond.torika.10": "Наш сад я защищу сама.",
  "bond.rex.0": "Не трогай меня.",
  "bond.rex.1": "Не страшно?",
  "bond.rex.2": "Любопытно.",
  "bond.rex.3": "Приходи и на следующую охоту.",
  "bond.rex.4": "Я запомнила твой запах.",
  "bond.rex.5": "Не отходи от меня.",
  "bond.rex.6": "Кто сунется к тебе — укушу.",
  "bond.rex.7": "Сегодня опять поздно.",
  "bond.rex.8": "Твой голос мне милее приказов.",
  "bond.rex.9": "Ты — моя единственная стая.",
  "bond.rex.10": "Я навсегда на твоей стороне.",
  "bond.spino.0": "…Что такое?",
  "bond.spino.1": "Скучаю по воде.",
  "bond.spino.2": "Можно и помолчать.",
  "bond.spino.3": "Расскажи о себе ещё.",
  "bond.spino.4": "Сегодня волны спокойны.",
  "bond.spino.5": "Люблю гулять вместе.",
  "bond.spino.6": "Если опасно — за мою спину.",
  "bond.spino.7": "Я знала, что ты придёшь.",
  "bond.spino.8": "Я уже привыкла к этому городу.",
  "bond.spino.9": "Рядом с тобой — моя вода.",
  "bond.spino.10": "Поплывём вместе куда угодно.",
  "bond.generic.0": "Всё ещё немного непривычно.",
  "bond.generic.1": "Снова встретились сегодня.",
  "bond.generic.2": "Понемногу привыкаю.",
  "bond.generic.3": "Пойдём на задание вместе.",
  "bond.generic.4": "Хорошо, когда ты рядом.",
  "bond.generic.5": "Можешь побыть рядом.",
  "bond.generic.6": "И в этот раз помогу.",
  "bond.generic.7": "Тебя здесь ждали.",
  "bond.generic.8": "Мы хорошие товарищи.",
  "bond.generic.9": "Хочу быть вместе долго.",
  "bond.generic.10": "Дальше рассчитываю на тебя.",
