  "observation.rex-small-etiquette.rex-small-example.tag": "Личный пример",
  "observation.spino-night-alarm.prompt": "А если во время ночного обхода одновременно сработают тревога резервуара и вызов спасателей из другой зоны?",
  "observation.spino-night-alarm.spino-alarm-rescue.label": "Коротко докладывает место спасения и сразу идёт туда",
  "observation.spino-night-alarm.spino-alarm-rescue.tag": "Задание прежде всего",
  "observation.spino-night-alarm.spino-alarm-command.label": "Поручает проверку резервуара ближайшему охраннику и расчищает путь спасения",
  "observation.spino-night-alarm.spino-alarm-command.tag": "Хладнокровное командование",
  "observation.spino-aquarium-decoration.prompt": "А если исследователь заметит в аквариуме новое украшение?",
  "observation.spino-aquarium-decoration.spino-decoration-deny.label": "Говорит, что оно всегда там было, отводит взгляд и лишь поправляет угол",
  "observation.spino-aquarium-decoration.spino-decoration-deny.tag": "Неумелое притворство",
  "observation.spino-aquarium-decoration.spino-decoration-shelter.label": "Коротко объясняет, что рыбам нужно укрытие",
  "observation.spino-aquarium-decoration.spino-decoration-shelter.tag": "Скрытая доброта",
  "observation.spino-aquarium-cleaning.prompt": "А если исследователь предложит помочь с непривычной чисткой аквариума?",
  "observation.spino-aquarium-cleaning.spino-cleaning-gloves.label": "Начинает отказываться, а потом молча протягивает запасные перчатки",
  "observation.spino-aquarium-cleaning.spino-cleaning-gloves.tag": "Безмолвное доверие",
  "observation.spino-aquarium-cleaning.spino-cleaning-roles.label": "Берёт на себя водоросли и чётко распределяет обязанности",
  "observation.spino-aquarium-cleaning.spino-cleaning-roles.tag": "Практичная забота",
  "observation.luka-sofa-conversation.prompt": "Как реагирует Лука, когда исследователь заговаривает с ним на диване лаборатории?",
  "observation.luka-sofa-conversation.luka-sofa-silence.label": "Освобождает место и наслаждается уютным молчанием бок о бок",
  "observation.luka-sofa-conversation.luka-sofa-silence.tag": "Непринуждённая близость",
