  "observation.luka-sofa-conversation.luka-sofa-chat.tag": "Болтливое дружелюбие",
  "observation.luka-sprint-rival.prompt": "Как он бежит, встав на старт рядом с другим хищным Реликтом?",
  "observation.luka-sprint-rival.luka-sprint-compete.label": "По сигналу выкладывается ради рекорда",
  "observation.luka-sprint-rival.luka-sprint-compete.tag": "Открытое соперничество",
  "observation.luka-sprint-rival.luka-sprint-pace.label": "Следит за шагом соседа и бежит к финишу вместе",
  "observation.luka-sprint-rival.luka-sprint-pace.tag": "Подстройка под чужой темп",
  "observation.luka-cheesecake-weight.prompt": "Что ты делаешь, когда Лука после чизкейка начинает переживать о весе?",
  "observation.luka-cheesecake-weight.luka-cake-training.label": "Убирает оставшуюся тарелку и пишет следующий план спринтерских тренировок",
