  "relic.raitia-grass.name": "Вирия",
  "relic.raitia-grass.origin": "Соня",
  "relic.raitia-grass.excavationSite": "Отложения карстовой пещеры, Словения",
  "relic.raitia-grass.fossilRecord": "Из одного слоя пещерных отложений извлекли десятки черепов одного вида. Пять из них так совпадают по размеру и зубам, что их отнесли к одному помёту.",
  "relic.raitia-grass.catalogSummary": "Образец на основе сони с увеличенными резцами и защёчными мешками.",
  "relic.raitia-grass.squadNote": "Расходная масса Истребления. Они разом текут туда, куда укажут, заполняя коридор, и задние шагают прямо через место, где пали передние.",
  "relic.raitia-grass.researcherTitle": "Исследователь",
  "relic.raitia-grass.unlockRecord": "Запись об идентификации 207. Подтверждена принадлежность к Истреблению. Из пяти в капюшонных пижамах с мышиными ушками это — с зелёным узлом; бросаются в глаза сумочка в форме сыра, тапочки с зубами и полосатый хвост с лентой на конце. Найдя еду, оно подавало знак не писком, а звуком резцов, и услышавшие сёстры разом сбегались в одно место. Там, где оно грызло, оставались рассыпанные свежие ростки, а в каждом следе на его пути прорастали семена, и за ним тянулась зелёная тропа. Почему оно не перестаёт есть даже в пору спячки, не подтверждено.",
  "relic.raitia-grass.observation.originYear": "Около 2 млн лет назад",
  "relic.raitia-grass.observation.restorationYear": "E.C. 2",
  "relic.raitia-grass.observation.lifeStage": "Юная",
  "relic.raitia-grass.observation.height": "0,94 м",
  "relic.raitia-grass.observation.weight": "21 кг",
  "relic.raitia-grass.passive.name": "Спячка",
  "relic.raitia-grass.passive.desc": "Раз за бой, когда ОЗ падают до половины или ниже, 5 секунд восстанавливает по 3% макс. ОЗ в секунду.",
  "relic.raitia-grass.ferocity.name": "Обжорство",
  "relic.raitia-grass.basic.name": "Грызь резцами",
  "relic.raitia-grass.ultimate.name": "Опустошение защёчных мешков",
  "relic.raitia-grass.projectName": "ANNIHILATION SWARM — Перекормленная популяция",
  "relic.raitia-water.name": "Гуттия",
  "relic.raitia-water.origin": "Соня",
  "relic.raitia-water.excavationSite": "Отложения карстовой пещеры, Словения",
  "relic.raitia-water.fossilRecord": "Из одного слоя пещерных отложений извлекли десятки черепов одного вида. Пять из них так совпадают по размеру и зубам, что их отнесли к одному помёту.",
  "relic.raitia-water.catalogSummary": "Образец на основе сони с увеличенными резцами и защёчными мешками.",
  "relic.raitia-water.squadNote": "Расходная масса Истребления. Они разом текут туда, куда укажут, заполняя коридор, и задние шагают прямо через место, где пали передние.",
  "relic.raitia-water.researcherTitle": "Исследователь",
  "relic.raitia-water.unlockRecord": "Запись об идентификации 208. Подтверждена принадлежность к Истреблению. Среди таких же капюшонных пижам это — с голубым полосатым хвостом и ватным комком на конце; улыбается, одна рука на поясе, пальцы другой у уголка рта. Услышав стук резцов сестры, она с улыбкой выбегала первой, а приблизившись, прежде всего грызла резцами то снаряжение, что оказывалось под рукой. Там, где прошла стая, тянулась длинная цепочка мокрых следов. Что смачивает эти следы, не подтверждено.",
  "relic.raitia-water.observation.originYear": "Около 2 млн лет назад",
  "relic.raitia-water.observation.restorationYear": "E.C. 2",
  "relic.raitia-water.observation.lifeStage": "Юная",
