  "relic.raitia-fire.name": "Фавия",
  "relic.raitia-fire.origin": "Соня",
  "relic.raitia-fire.excavationSite": "Отложения карстовой пещеры, Словения",
  "relic.raitia-fire.fossilRecord": "Из одного слоя пещерных отложений извлекли десятки черепов одного вида. Пять из них так совпадают по размеру и зубам, что их отнесли к одному помёту.",
  "relic.raitia-fire.catalogSummary": "Образец на основе сони с увеличенными резцами и защёчными мешками.",
  "relic.raitia-fire.squadNote": "Расходная масса Истребления. Они разом текут туда, куда укажут, заполняя коридор, и задние шагают прямо через место, где пали передние.",
  "relic.raitia-fire.researcherTitle": "Исследователь",
  "relic.raitia-fire.unlockRecord": "Запись об идентификации 209. Подтверждена принадлежность к Истреблению. Среди таких же капюшонных пижам это — с розовым клетчатым бантом; стоит с не до конца проснувшимся лицом, одной рукой трёт глаза, другая на поясе. Несмотря на сонный вид, оно не переставало есть и продолжало грызть резцами, даже когда защёчные мешки были полны. Когда сёстры бросались вперёд, оно шло следом, протирая глаза. Сонливость это притворство или настоящая, не подтверждено.",
  "relic.raitia-fire.observation.originYear": "Около 2 млн лет назад",
  "relic.raitia-fire.observation.restorationYear": "E.C. 2",
  "relic.raitia-fire.observation.lifeStage": "Юная",
  "relic.raitia-fire.observation.height": "0,94 м",
  "relic.raitia-fire.observation.weight": "21 кг",
  "relic.raitia-fire.passive.name": "Спячка",
  "relic.raitia-fire.passive.desc": "Раз за бой, когда ОЗ падают до половины или ниже, 5 секунд восстанавливает по 3% макс. ОЗ в секунду.",
  "relic.raitia-fire.ferocity.name": "Обжорство",
  "relic.raitia-fire.basic.name": "Грызь резцами",
