  "relic.raitia-earth.name": "Силия",
  "relic.raitia-earth.origin": "Соня",
  "relic.raitia-earth.excavationSite": "Отложения карстовой пещеры, Словения",
  "relic.raitia-earth.fossilRecord": "Из одного слоя пещерных отложений извлекли десятки черепов одного вида. Пять из них так совпадают по размеру и зубам, что их отнесли к одному помёту.",
  "relic.raitia-earth.catalogSummary": "Образец на основе сони с увеличенными резцами и защёчными мешками.",
  "relic.raitia-earth.squadNote": "Расходная масса Истребления. Они разом текут туда, куда укажут, заполняя коридор, и задние шагают прямо через место, где пали передние.",
  "relic.raitia-earth.researcherTitle": "Исследователь",
  "relic.raitia-earth.unlockRecord": "Запись об идентификации 210. Подтверждена принадлежность к Истреблению. Среди таких же капюшонных пижам это бросается в глаза коричневой основой, жёлтым узлом и заплетённой косой; на кончике хвоста — большой пушистый ком. Когда оно стояло, вытянув руки вперёд, сёстры разом текли в сторону его кончиков пальцев, а там, где падала передняя, задняя просто перешагивала через неё. Кто определяет, куда указывают его пальцы, не подтверждено.",
  "relic.raitia-earth.observation.originYear": "Около 2 млн лет назад",
  "relic.raitia-earth.observation.restorationYear": "E.C. 2",
